* { box-sizing: border-box; margin: 0; padding: 0; }
.pinv {
  width: 100%; max-width: 680px; margin: 0 auto;
  background: #fff;

  border-radius: 8px;
  overflow: hidden;
  font-family: 'DM Sans', 'Segoe UI', sans-serif;
  font-size: 10px;
  color: #1e293b;
}
.pinv-header {
  padding: 16px 20px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  background: #fff;
}
.pinv-header-right { text-align: right; }
.pinv-doc-type {
  font-size: 9px; font-weight: 700; letter-spacing: 0.12em;
  text-transform: uppercase; color: #64748b;
}
.pinv-doc-num {
  font-family: 'DM Mono', monospace; font-size: 18px;
  font-weight: 500; color: #0f1f3d; letter-spacing: 0.02em; margin-top: 2px;
}
.pinv-doc-sub { font-size: 8px; color: #64748b; margin-top: 3px; }
.pinv-doc-sub span { font-weight: 600; color: #1e293b; }

.pinv-stripe { height: 3px; background: linear-gradient(90deg, #2563eb 0%, #0ea5b0 50%, #c9972a 100%); }

.pinv-meta {
  display: flex;
  border-bottom: 0.5px solid #e2e8f0;
}
.pinv-meta-cell {
  flex: 1; padding: 9px 14px;
  border-right: 0.5px solid #e2e8f0;
}
.pinv-meta-cell:last-child { border-right: none; }
.pinv-meta-lbl { font-size: 7px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: #64748b; margin-bottom: 2px; }
.pinv-meta-val { font-size: 10px; font-weight: 600; color: #1e293b; }
.pinv-meta-val.accent { color: #2563eb; }
.pinv-status {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 8px; border-radius: 20px; font-size: 7.5px;
  font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em;
}
.pinv-status-dot { width: 5px; height: 5px; border-radius: 50%; background: currentColor; display: inline-block; }

.pinv-parties {
  display: grid; grid-template-columns: 1fr 1fr;
  border-bottom: 0.5px solid #e2e8f0;
}
.pinv-party { padding: 12px 16px; border-right: 0.5px solid #e2e8f0; }
.pinv-party:last-child { border-right: none; }
.pinv-party-hd {
  font-size: 7px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.12em; color: #2563eb;
  border-bottom: 1.5px solid #dbeafe;
  padding-bottom: 4px; margin-bottom: 8px;
}
.pinv-party-name { font-size: 11px; font-weight: 700; color: #0f1f3d; margin-bottom: 3px; }
.pinv-party-det { font-size: 8.5px; color: #64748b; margin-bottom: 1px; }
.pinv-party-det span { font-weight: 600; color: #1e293b; }

.pinv-items { padding: 0 16px; margin-top: 12px; }
.pinv-sec-title { font-size: 7px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.12em; color: #64748b; margin-bottom: 6px; }

table.pinv-table { width: 100%; border-collapse: collapse; }
table.pinv-table thead tr { background: #f1f5f9; }
table.pinv-table thead th {
  color: #475569; font-size: 7.5px; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em;
  padding: 7px 10px; text-align: left;
  border-bottom: 1.5px solid #cbd5e1;
}
table.pinv-table thead th.r { text-align: right; }
table.pinv-table tbody tr { border-bottom: 0.5px solid #e2e8f0; }
table.pinv-table tbody tr:nth-child(even) { background: #f8fafc; }
table.pinv-table tbody td { padding: 8px 10px; font-size: 9px; color: #1e293b; vertical-align: top; }
table.pinv-table tbody td.r { text-align: right; font-family: 'DM Mono', monospace; }
.pinv-item-name { font-weight: 600; color: #0f1f3d; }
.pinv-item-grp { font-size: 7.5px; color: #64748b; margin-top: 1px; }

.pinv-totals { display: flex; justify-content: flex-end; padding: 12px 16px 0; }
.pinv-totals-box { width: 220px; border: 0.5px solid #e2e8f0; border-radius: 6px; overflow: hidden; }
.pinv-tot-row { display: flex; justify-content: space-between; padding: 5px 12px; font-size: 9px; border-bottom: 0.5px solid #e2e8f0; }
.pinv-tot-row:last-child { border-bottom: none; }
.pinv-tot-lbl { color: #64748b; }
.pinv-tot-val { font-family: 'DM Mono', monospace; font-weight: 600; color: #1e293b; }
.pinv-grand {
  background: #f8fafc;
  border-top: 1.5px solid #cbd5e1;
  padding: 8px 12px;
  display: flex; justify-content: space-between; align-items: center;
}
.pinv-grand-lbl { font-size: 8px; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: #475569; }
.pinv-grand-val { font-family: 'DM Mono', monospace; font-size: 13px; font-weight: 700; color: #0f1f3d; }

.pinv-words {
  margin: 10px 16px 0;
  padding: 6px 12px;
  background: #fffbeb;
  border-left: 3px solid #c9972a;
  font-size: 8.5px; color: #64748b; font-style: italic;
}
.pinv-words strong { color: #1e293b; font-style: normal; }

.pinv-remarks {
  margin: 8px 16px 0;
  padding: 7px 12px;
  background: #f8fafc;
  border: 0.5px solid #e2e8f0;
  border-radius: 4px;
  font-size: 8.5px; color: #64748b;
}
.pinv-remarks strong { display: block; font-size: 7px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: #2563eb; margin-bottom: 2px; }

.pinv-footer {
  margin-top: 16px;
  border-top: 0.5px solid #e2e8f0;
  padding: 10px 16px;
  display: flex; justify-content: space-between; align-items: center;
  background: #f8fafc;
}
.pinv-foot-addr { font-size: 7.5px; color: #64748b; line-height: 1.6; }
.pinv-foot-addr strong { color: #1e293b; }
.pinv-foot-right { font-size: 7px; color: #64748b; text-align: right; line-height: 1.6; }

@media print {
  body { background: #fff; }
  .pinv { border: none; border-radius: 0; }
}

html:
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead, footer, print_settings=None, print_heading_template=None) -%}
	{% if letter_head and not no_letterhead %}
		<div class="letter-head">{{ letter_head }}</div>
	{% endif %}
	{% if print_heading_template %}
		{{ frappe.render_template(print_heading_template, {"doc":doc}) }}
	{% endif %}
{%- endmacro -%}

{% for page in layout %}
<div class="page-break invoice-wrapper">
	<div {% if print_settings.repeat_header_footer %} id="header-html" class="hidden-pdf" {% endif %}>
		{{ add_header(loop.index, layout|len, doc, letter_head, no_letterhead, footer, print_settings) }}
	</div>
	{%- if doc.meta.is_submittable and doc.docstatus==2-%}
		<div class="text-center" document-status="cancelled">
			<h4 style="margin-top: 20px;">{{ _("CANCELLED") }}</h4>
		</div>
	{%- endif -%}
	{%- if doc.meta.is_submittable and doc.docstatus==0 and (print_settings==None or print_settings.add_draft_heading) -%}
		<div class="text-center" document-status="draft">
			<h4 style="margin-top: 20px !important;">{{ _("DRAFT") }}</h4>
		</div>
	{%- endif -%}

	<style>
		.letter-head {
			margin-top: 12px !important;
		}
		.invoice-wrapper {
			font-family: "Inter", sans-serif;
			color: var(--black-overlay-700);
		}

		.print-format-body {
			padding: 30px 12px 12px 12px !important;
		}

		body {
			margin-bottom: 0mm !important;
			padding: 0px !important;
		}

		table.info-table,
		table.items-table,
		table.tax-table {
			border-collapse: separate;
			border-spacing: 0;
			border: 1px solid #ededed;
			border-radius: 10px;
			overflow: hidden;
		}

		table.info-table td {
			border-bottom: 1px solid #ededed;
			padding: 8px 10px !important;
		}
		table.items-table td,
		table.tax-table td {
			border-bottom: 1px solid #ededed;
			padding: 8px;
		}

		table.info-table td:not(:first-of-type),
		table.items-table td:not(:first-of-type),
		table.tax-table td:not(:first-of-type) {
			border-left: 1px solid #ededed;
		}

		table.info-table tbody tr:last-of-type td,
		table.items-table tbody tr:last-of-type td,
		table.tax-table tbody tr:last-of-type td {
			border-bottom: none;
		}

		thead.table-header {
			background: #f8f8f8;
		}
		thead.table-header td {
			color: #7c7c7c;
		}

		.text-center {
			text-align: center;
		}
		.text-left {
			text-align: left;
		}
		.text-right {
			text-align: right;
		}
		.text-muted {
			color: #7c7c7c;
		}
		.text-dark {
			color: #525252;
		}
		.text-bold {
			font-weight: bold;
		}
		.small-text {
			color: #666;
		}

		.mt-10 {
			margin-top: 10px;
		}
		.mt-15 {
			margin-top: 15px;
		}
		.mt-20 {
			margin-top: 20px;
		}
		.mt-40 {
			margin-top: 40px;
		}
		.mt-80 {
			margin-top: 80px;
		}
		.mb-20 {
			margin-bottom: 20px;
		}
		.pb-8 {
			padding-bottom: 8px;
		}
		.amount-width {
			width: 110px;
		}

		.totals-table {
			border-radius: 5px;
			width: 100%;
		}
		.totals-table td {
			padding: 4px 8px;
		}
		.totals-table tr {
			border-bottom: 1px solid #ededed;
			position: relative;
		}
		.totals-table tr td {
			position: relative;
		}
		.totals-table tr td div {
			width: 12%;
			height: 14px;
			background-color: white;
			position: absolute;
			bottom: -6px;
			left: 0%;
			color: white;
		}
		.totals-table tr:last-child {
			border-bottom: none;
		}
		.totals-table .grand-total td {
			padding: 6px 8px;
			font-weight: bold;
		}

		.words-box {
			background: #f8f8f8;
			border-radius: 8px;
			padding: 8px;
			line-height: 21px;
			letter-spacing: 0.21px;
			font-size: small;
		}

		.info-card {
			color: #7c7c7c;
		}

		.title {
			color: #7c7c7c !important;
		}

		.heading {
			color: #525252 !important;
			font-weight: 300;
		}

		.print-format {
			color: #171717;
			font-size: 14px;
			font-style: normal;
			font-weight: 420;
			line-height: 21px;
			padding: 0px;
			letter-spacing: 0.14px;
			margin-left: 0mm !important;
			margin-right: 0mm !important;
		}
		.letter-head-footer {
			margin-top: 0px !important;
		}
		.print-heading {
			margin-top: 0px !important;
			margin-bottom: 0px !important;
			padding-bottom: 0px !important;
		}
	</style>
	<div class="print-format-body">
		<table class="info-table mb-20" style="width: 100%">
			<tr>
				<td style="width: 50%">
					<span class="heading">{{ _("Customer Name") }}:</span> {{doc.customer_name }}
				</td>
				<td style="width: 50%">
					<span class="heading">{{ _("Payment Due Date") }}:</span> {{
					frappe.utils.format_date(doc.due_date) }}
				</td>
			</tr>
			<tr>
				<td><span class="heading">{{ _("Invoice Number") }}:</span> {{ doc.name }}</td>
				<td>
					<span class="heading">{{ _("Invoice Date") }}:</span> {{
					frappe.utils.format_date(doc.posting_date) }}
				</td>
			</tr>
			<tr>
				<td><span class="heading">{{ _("Bill From") }}:</span><br />
					{% if doc.company_address %}
                        {% set company_address = frappe.db.get_value("Address", doc.company_address, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
                        {{  doc.company }}<br>
                        {{ company_address.get("address_line1") or "" }}<br>
                        {% if company_address.get("address_line2") %}{{ company_address.get("address_line2") }}<br>{% endif %}
                        {{ company_address.get("city") or "" }}, {{ company_address.get("state") or "" }} {{ company_address.get("pincode") or "" }}, {{ company_address.get("country") or "" }}<br>
                    {% endif %}
				</td>
				<td><span class="heading">{{ _("Bill To") }}:</span><br />
				    {% if doc.customer_address %}
						{% set customer_address = frappe.db.get_value("Address", doc.customer_address, ["address_line1", "address_line2", "city", "state", "pincode", "country"], as_dict=True) %}
                        {{ doc.customer_name }}<br>
						{{ customer_address.address_line1 or "" }}<br>
						{% if customer_address.address_line2 %}{{ customer_address.address_line2 }}<br>{% endif %}
						{{ customer_address.city or "" }} {{ customer_address.state or "" }} {{ customer_address.pincode or "" }} {{ customer_address.country or "" }}<br>
					{% endif %}
				</td>
			</tr>
		</table>

		<!-- Items Table -->
		{% set item_naming_by = frappe.db.get_single_value("Stock Settings", "item_naming_by") %}
		<table class="items-table mt-15" style="width: 100%">
			<thead class="table-header">
				<tr>
					<td class="text-center">{{ _("No") }}</td>
					<td class="text-left">{{ _("Item") }}</td>
					{% if item_naming_by != "Item Code" %}
						<td class="text-left">{{ _("Item Code") }}</td>
					{% endif %}
					<td class="text-right">{{ _("Quantity") }}</td>
					<td class="text-right">{{ _("Rate") }}</td>
					<td class="text-right">{{ _("Amount") }}</td>
				</tr>
			</thead>
			<tbody>
				{% for item in doc.items %}
				<tr>
					<td class="text-center text-dark">{{ loop.index }}</td>
					<td>{{ item.item_name }}</td>
					{% if item_naming_by != "Item Code" %}
						<td class="text-left">{{ item.item_code }}</td>
					{% endif %}
					<td class="text-right text-dark">{{ item.get_formatted("qty", 0) }} {{ item.uom }}</td>
					<td class="text-right text-dark">{{ item.get_formatted("net_rate", doc) }}</td>
					<td class="text-right" style="color: #171717">
						{{ item.get_formatted("net_amount", doc) }}
					</td>
				</tr>
				{% endfor %}
			</tbody>
		</table>

		<!-- Totals Section -->
		<table style="width:100%; margin-top: 15px">
			<td style="vertical-align: bottom !important; width: 60%;">
				<p class="title">{{ _("Total in words") }}</p>
				<div class="words-box text-uppercase">{{ doc.in_words }}</div>
			</td>
			<td>
				&nbsp;
			</td>
			<td style="width: 38%;">
				<table class="totals-table">
					<tr>
						<td class="text-right text-muted"><div></div>{{ _("Sub Total:") }}</td>
						<td class="text-right amount-width">{{ doc.get_formatted("total", doc) }}</td>
					</tr>
					{%- if doc.apply_discount_on == "Net Total" -%}
						<tr>
							<td class="text-right text-muted">
								<div></div>{{ _("Discount") }} ({{ doc.additional_discount_percentage }}%):
							</td>
							<td class="text-right amount-width">{{ doc.get_formatted("discount_amount", doc) }}</td>
						</tr>
					{%- endif -%}
					{%- for tax in doc.taxes -%}
						{%- if (tax.tax_amount or print_settings.print_taxes_with_zero_amount) and (not tax.included_in_print_rate or doc.flags.show_inclusive_tax_in_print) -%}
							<tr>
								<td class="text-right text-muted"><div></div>{{ tax.get_formatted("description") }} ({{ tax.get_formatted("rate") }}%):</td>
								<td class="text-right amount-width">{{ tax.get_formatted("tax_amount") }}</td>
							</tr>
						{%- endif -%}
					{%- endfor -%}
					{%- if doc.apply_discount_on == "Grand Total" -%}
						<tr>
							<td class="text-right text-muted">
								<div></div>{{ _("Discount") }} ({{ doc.additional_discount_percentage }}%):
							</td>
							<td class="text-right amount-width">{{ doc.get_formatted("discount_amount", doc) }}</td>
						</tr>
					{%- endif -%}
					<tr class="grand-total">
						<td class="text-right">{{ _("Grand Total:") }}</td>
						<td class="text-right amount-width">{{ doc.get_formatted("grand_total", doc) }}</td>
					</tr>
				</table>
			</td>
		</table>
	{% if doc.security_code %}
<div class="text-center">
    <img width="120px" src="{{ doc.qr_code }}" class="" /><br>
    <b>Código de seguridad:</b> {{doc.security_code}}<br>
    <b>Fecha firma digital:</b> 08-05-2025 17:52:03
</div>
{%endif%}
		<!-- Terms -->
		<div class="terms-section">
			{% if doc.terms %}
			<div class="info-card mt-40">
				<div>{{ _("Terms and Conditions") }}</div>
				{{ doc.terms}}
			</div>
			{% endif %}
	</div>
</div>
{% endfor %}
